//! Browser settings are authored through the shared command engine. No CEF
//! initialization, file reads or URL requests run in this view.
use eframe::egui;
use skylive_core::{BrowserSource,BrowserLocation,Command,Id};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Edit {Add {scene:Id},Rebind {source:Id}}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Submission {pub token:u64,pub session:u64,pub revision:u64,pub edit:Edit,pub name:String,pub browser:BrowserSource}
impl Submission {pub fn command(&self)->Command{match self.edit {Edit::Add {scene}=>Command::AddBrowserSource {scene,name:self.name.clone(),browser:self.browser.clone()},Edit::Rebind {source}=>Command::SetBrowserSource {source,browser:self.browser.clone()}}}}
pub struct Draft {pub token:u64,pub session:u64,pub revision:u64,pub edit:Edit,pub name:String,pub local:bool,pub url:String,pub path:String,pub css:String,pub width:u32,pub height:u32,pub fps:u32,pub shutdown:bool,pub refresh_active:bool,pub control_audio:bool,pub runtime_problem:Option<String>,original:Option<BrowserSource>}
impl Draft {
 pub fn add(scene:Id,name:String)->Self{Self {token:0,session:0,revision:0,edit:Edit::Add {scene},name,local:false,url:"https://obsproject.com/browser-source".into(),path:String::new(),css:"body { background-color: rgba(0, 0, 0, 0); margin: 0; overflow: hidden; }".into(),width:800,height:600,fps:30,shutdown:false,refresh_active:false,control_audio:false,runtime_problem:None,original:None}}
 pub fn rebind(source:Id,browser:&BrowserSource)->Self{let mut d=Self::add(source,String::new());d.edit=Edit::Rebind {source};match browser.location(){BrowserLocation::Url {url}=>d.url=url.clone(),BrowserLocation::LocalFile {path}=>{d.local=true;d.path=path.clone();}}d.css=browser.css().into();d.width=browser.width();d.height=browser.height();d.fps=browser.fps();d.shutdown=browser.shutdown_when_hidden();d.refresh_active=browser.refresh_when_active();d.control_audio=browser.control_audio();d.original=Some(browser.clone());d}
 pub fn title(&self)->&'static str{if matches!(self.edit,Edit::Add {..}){"Add Browser Source"}else{"Properties: Browser Source"}}
 pub fn request(&self)->Result<Submission,String>{let location=if self.local{BrowserLocation::LocalFile {path:self.path.clone()}}else{BrowserLocation::Url {url:self.url.clone()}};let browser=BrowserSource::new(location,self.css.clone(),self.width,self.height,self.fps,self.shutdown,self.refresh_active).map(|value|value.with_control_audio(self.control_audio)).map_err(|e|e.to_string())?;Ok(Submission {token:self.token,session:self.session,revision:self.revision,edit:self.edit,name:self.name.clone(),browser})}
 pub fn unchanged(&self)->bool{self.request().is_ok_and(|r|self.original.as_ref()==Some(&r.browser))}
}
pub fn editor(ui:&mut egui::Ui,d:&mut Draft,intents:&mut Vec<super::Intent>){
 if matches!(d.edit,Edit::Add {..}){let label=ui.label(crate::i18n::tr(ui,"Name"));ui.add(egui::TextEdit::singleline(&mut d.name).char_limit(256).desired_width(ui.available_width())).labelled_by(label.id).on_hover_text(crate::i18n::tr(ui,"Name this Browser Source in the scene."));}
 ui.checkbox(&mut d.local,crate::i18n::tr(ui,"Local HTML file")).on_hover_text(crate::i18n::tr(ui,"Load an explicitly chosen HTML file instead of an HTTP or HTTPS URL."));
 let label=ui.label(crate::i18n::tr(ui,if d.local{"HTML file path"}else{"URL"}));if d.local {ui.add(egui::TextEdit::singleline(&mut d.path).char_limit(4096).desired_width(ui.available_width())).labelled_by(label.id).on_hover_text(crate::i18n::tr(ui,"Absolute HTML path. CEF resolves the page's relative image, script and CSS resources."));}else{ui.add(egui::TextEdit::singleline(&mut d.url).char_limit(16384).desired_width(ui.available_width())).labelled_by(label.id).on_hover_text(crate::i18n::tr(ui,"HTTP or HTTPS page rendered by the matching CEF runtime; redirects and web animations use the actual browser engine."));}
 egui::Grid::new("browser-viewport").num_columns(2).show(ui,|ui|{for (label,value,min,max) in [("Width",&mut d.width,1,4096),("Height",&mut d.height,1,4096),("FPS",&mut d.fps,1,60)]{ui.label(crate::i18n::tr(ui,label));ui.add(egui::DragValue::new(value).range(min..=max)).on_hover_text(crate::i18n::tr(ui,"Actual CEF offscreen viewport and maximum paint rate; total viewport is limited to 8.8 megapixels."));ui.end_row();}});
 ui.label(crate::i18n::tr(ui,"Custom CSS"));ui.add(egui::TextEdit::multiline(&mut d.css).char_limit(65536).desired_width(ui.available_width()).desired_rows(6).code_editor()).on_hover_text(crate::i18n::tr(ui,"Inject this CSS into the main document after loading. The page's own content policy can restrict inline styles."));
 ui.checkbox(&mut d.shutdown,crate::i18n::tr(ui,"Shutdown source when not visible")).on_hover_text(crate::i18n::tr(ui,"Close the CEF page when no active video output shows this source; opening it again waits for a new real paint."));
 ui.checkbox(&mut d.refresh_active,crate::i18n::tr(ui,"Refresh when Program becomes active")).on_hover_text(crate::i18n::tr(ui,"Recreate this page on transition from inactive to Program-visible. Preview and virtual-camera-only visibility do not activate Program audio."));
 ui.checkbox(&mut d.control_audio,crate::i18n::tr(ui,"Control audio via SkyLive")).on_hover_text(crate::i18n::tr(ui,"Capture actual CEF48kHz stereo PCM into this source's mixer, audio filters and monitoring. When off, CEF plays through its native audio output and this source has no Program PCM route."));
 if let Edit::Rebind {source}=d.edit {if ui.add_enabled(d.unchanged(),egui::Button::new(crate::i18n::tr(ui,"Refresh Browser"))).on_hover_text(crate::i18n::tr(ui,"Close and reload this page; old paints and inputs keep their old browser lease.")).on_disabled_hover_text(crate::i18n::tr(ui,"Apply or cancel changed browser settings before refreshing.")).clicked(){intents.push(super::Intent::RefreshBrowser {token:d.token,session:d.session,revision:d.revision,source});}}
 ui.small(crate::i18n::tr(ui,"Requires the matching CEF 127.145.7 runtime and Rust browser helper on Windows x64. No browser DLL from OBS is loaded as a plugin."));
 ui.small(crate::i18n::tr(ui,"Controlled browser audio uses actual CEF48kHz stereo PCM and the shared Program converter. Browser JavaScript bindings and browser docks are not included yet."));
 ui.small(crate::i18n::tr(ui,"New windows, external apps, downloads, native file dialogs and JavaScript modal dialogs are suppressed. HTML dropdown popups are composited within the source."));
 if let Some(error)=&d.runtime_problem {ui.colored_label(ui.visuals().warn_fg_color,crate::i18n::tf(ui,"Browser runtime: {error}",&[("{error}",error.clone())]));}
}
